//! What crosses the bridge to the webview: the core's [`wtm_core::Model`]
//! as plain JSON, shaped for the page rather than for the core.
//!
//! The core's own types stay free of serialisation for this purpose (most
//! of `Model` has none, and the snapshot's format must not move with the
//! UI's needs). Each type here derives its TypeScript twin into
//! `ui/src/wire/`, regenerated by `cargo test -p wtm-tauri`.

use serde::{Deserialize, Serialize};
use ts_rs::TS;
use wtm_core::paths::{slugify_branch, tildify};

/// Everything the window shows that comes from the core.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Model {
    pub repos: Vec<Repo>,
    pub notice: Option<Notice>,
    /// A full refresh is running.
    pub refreshing: bool,
    /// The background fetch is running.
    pub fetching: bool,
    pub settings: Settings,
}

/// The app-wide settings, as the Settings sheet edits them.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Settings {
    pub worktrees_root: String,
    /// Takes a `{path}` placeholder, else the path is appended.
    pub editor_command: String,
    /// New worktrees get the files a repo's `.worktreeinclude` names.
    pub copy_worktree_include: bool,
    pub update_channel: UpdateChannel,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum UpdateChannel {
    Stable,
    Beta,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Repo {
    pub id: String,
    pub name: String,
    pub path: String,
    /// `path` with the home directory abbreviated to `~`.
    pub display_path: String,
    pub main_branch: String,
    /// Run in each new worktree once it is created.
    pub init_command: String,
    /// Local branches, for the branch picker.
    pub branches: Vec<String>,
    /// What a new branch starts from unless the sheet says otherwise:
    /// `origin/<trunk>` when that exists, else the trunk.
    pub default_base_ref: String,
    /// Refs offered as a new branch's base.
    pub base_ref_candidates: Vec<String>,
    /// Why listing failed, if it did.
    pub error: Option<String>,
    /// False while only the cached snapshot from the last run is known.
    pub loaded: bool,
    /// Sorted as git and the core sort them: the primary tree first.
    pub worktrees: Vec<Worktree>,
    /// Creations git has not listed yet, and failed ones until dismissed.
    pub pending: Vec<Pending>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Worktree {
    pub path: String,
    pub display_path: String,
    /// `None` for a detached HEAD.
    pub branch: Option<String>,
    pub head: String,
    pub is_main: bool,
    pub locked: bool,
    /// Git still lists it, but the folder is gone.
    pub prunable: bool,
    /// An operation in flight on this worktree.
    pub busy: Option<Busy>,
    /// `None` if git could not say.
    pub status: Option<Status>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Status {
    pub has_staged: bool,
    pub has_unstaged: bool,
    pub has_untracked: bool,
    /// The ref `ahead`/`behind` count against.
    pub trunk_ref: String,
    pub ahead: Option<u32>,
    pub behind: Option<u32>,
    pub has_upstream: bool,
    /// Commits not on the upstream yet; 0 without one.
    pub unpushed: u32,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum Busy {
    Pushing,
    Pulling,
    Merging,
    Switching,
    Deleting,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Pending {
    #[ts(type = "number")]
    pub id: u64,
    pub branch: String,
    /// The folder the worktree will get, which is where it sorts among
    /// the listed ones.
    pub folder: String,
    pub error: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Notice {
    /// Grows with every notice, so the page can tell a repeated message
    /// from the one it already showed.
    #[ts(type = "number")]
    pub id: u64,
    pub tone: Tone,
    pub text: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum Tone {
    Info,
    Error,
}

/// Handed to the page before its first line runs (`window.__WTM_BOOT__`),
/// so the first paint already has the repos.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct Boot {
    pub model: Model,
    /// "Finder", "Files", "Explorer": for button captions.
    pub file_manager: String,
    /// `std::env::consts::OS`: "macos", "linux", "windows". The page draws
    /// its own title on macOS, where the toolbar sits in the title bar.
    pub os: String,
    /// How "Open in terminal" picks a terminal on this OS, for Settings.
    pub terminal_note: String,
    /// The list as it was left when the app last ran.
    pub view: ViewState,
    /// Whether the app's menu bar has the shortcuts (macOS). Then the page
    /// leaves those keys to the menu, which sends them back as `menu`
    /// events, rather than acting on a key the menu also acts on.
    pub menu_bar: bool,
}

// MARK: Window state

/// What the page keeps of the list between launches; the window's frame is
/// kept on the Rust side, which sees it move.
#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct ViewState {
    /// Repos whose cards are closed.
    pub closed_repos: Vec<String>,
    /// How far the list is scrolled, in CSS pixels (points).
    pub scroll: f64,
    pub focus: Option<RowFocus>,
}

/// The selected row, by identity: a repo's header, or one of its worktrees.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct RowFocus {
    pub repo_id: String,
    pub worktree_path: Option<String>,
}

impl ViewState {
    pub fn from_core(s: &wtm_core::UiState) -> Self {
        Self {
            closed_repos: s.collapsed_repos.iter().cloned().collect(),
            scroll: s.scroll,
            focus: s.focus.as_ref().map(|f| RowFocus {
                repo_id: f.repo_id.clone(),
                worktree_path: f.worktree_path.clone(),
            }),
        }
    }

    /// `state` with the page's part replaced; the frame is left as it was.
    pub fn apply(self, state: wtm_core::UiState) -> wtm_core::UiState {
        wtm_core::UiState {
            collapsed_repos: self.closed_repos.into_iter().collect(),
            // A NaN from a page bug must not reach the file.
            scroll: if self.scroll.is_finite() {
                self.scroll.max(0.0)
            } else {
                0.0
            },
            focus: self.focus.map(|f| wtm_core::Focus {
                repo_id: f.repo_id,
                worktree_path: f.worktree_path,
            }),
            ..state
        }
    }
}

/// Which of the menu's items can be chosen now; the page knows, from the
/// selection and any open dialog.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct MenuState {
    pub new_worktree: bool,
    pub switch_branch: bool,
    pub move_up: bool,
    pub move_down: bool,
}

// MARK: New Worktree

/// The New Worktree sheet's fields, sent on every change to be checked.
#[derive(Debug, Clone, PartialEq, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct NewWorktreeFields {
    pub repo_id: String,
    pub name: String,
    pub new_branch: bool,
    /// Empty for the repo's trunk.
    pub base: String,
}

/// The core's verdict on those fields (`wtm_core::new_worktree::check`):
/// what Create would send, or why it is off.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct NewWorktreeCheck {
    /// What Create sends; `None` while it is off.
    pub create: Option<CreateRequest>,
    /// Why Create is off. Empty while no name has been typed.
    pub problem: Option<String>,
    /// Said under the name when nothing is wrong.
    pub note: Option<String>,
    /// The branch comes from a remote, so the base field does not apply.
    pub from_remote: bool,
    /// Where the worktree would go, abbreviated with `~`.
    pub folder: Option<String>,
}

/// Create, exactly as the sheet's last check said it would.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct CreateRequest {
    pub repo_id: String,
    pub branch: String,
    pub source: BranchSource,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, TS)]
#[serde(rename_all = "camelCase", tag = "kind")]
#[ts(export)]
pub enum BranchSource {
    /// A new branch from `baseRef`, or the trunk when there is none.
    #[serde(rename_all = "camelCase")]
    New { base_ref: Option<String> },
    /// A local branch that exists already.
    Existing,
    /// Fetched from this remote, the only one that has it.
    Remote { remote: String },
}

impl BranchSource {
    pub fn from_core(s: wtm_core::BranchSource) -> Self {
        match s {
            wtm_core::BranchSource::New { base_ref } => BranchSource::New { base_ref },
            wtm_core::BranchSource::Existing => BranchSource::Existing,
            wtm_core::BranchSource::Remote(remote) => BranchSource::Remote { remote },
        }
    }

    pub fn to_core(self) -> wtm_core::BranchSource {
        match self {
            BranchSource::New { base_ref } => wtm_core::BranchSource::New { base_ref },
            BranchSource::Existing => wtm_core::BranchSource::Existing,
            BranchSource::Remote { remote } => wtm_core::BranchSource::Remote(remote),
        }
    }
}

impl CreateRequest {
    pub fn to_core(self) -> wtm_core::CreateWorktreeParams {
        wtm_core::CreateWorktreeParams {
            repo_id: self.repo_id,
            branch: self.branch,
            source: self.source.to_core(),
        }
    }
}

impl NewWorktreeCheck {
    /// Check `fields` against the model; `taken` is the folder for the name,
    /// as shown, when something is already there.
    pub fn new(m: &wtm_core::Model, fields: &NewWorktreeFields, taken: Option<&str>) -> Self {
        let node = m.repo(&fields.repo_id);
        let name = fields.name.trim();
        let place = node
            .map(|n| n.locate_branch(name))
            .unwrap_or(wtm_core::BranchLocation::Nowhere);
        let check = wtm_core::new_worktree::check(
            &fields.name,
            fields.new_branch,
            &fields.base,
            &place,
            taken,
        );
        let folder = node
            .filter(|_| !name.is_empty())
            .map(|n| tildify(&m.worktree_path(&n.repo, name).to_string_lossy(), &m.home));
        let (create, problem) = match check.create {
            Ok(source) => (
                Some(CreateRequest {
                    repo_id: fields.repo_id.clone(),
                    branch: name.to_string(),
                    source: BranchSource::from_core(source),
                }),
                None,
            ),
            Err(reason) => (None, Some(reason)),
        };
        Self {
            create,
            problem,
            note: check.note,
            from_remote: check.from_remote,
            folder,
        }
    }
}

// MARK: Repos and settings

/// What the repo settings sheet saves.
#[derive(Debug, Clone, PartialEq, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct RepoEdit {
    pub repo_id: String,
    pub name: String,
    pub main_branch: String,
    pub init_command: String,
}

impl RepoEdit {
    /// The repo as Save leaves it: a blank name keeps the old one, a blank
    /// trunk is `main` (as `wtm-ui`'s sheet saves it).
    pub fn apply(&self, repo: &wtm_core::RepoConfig) -> wtm_core::RepoConfig {
        let mut updated = repo.clone();
        if !self.name.trim().is_empty() {
            updated.name = self.name.trim().to_string();
        }
        updated.main_branch = match self.main_branch.trim() {
            "" => "main".into(),
            m => m.to_string(),
        };
        updated.init_command = self.init_command.clone();
        updated
    }
}

impl Settings {
    pub fn to_core(&self) -> wtm_core::AppSettings {
        wtm_core::AppSettings {
            worktrees_root: self.worktrees_root.trim().to_string(),
            editor_command: self.editor_command.trim().to_string(),
            update_channel: match self.update_channel {
                UpdateChannel::Stable => wtm_core::update::UpdateChannel::Stable,
                UpdateChannel::Beta => wtm_core::update::UpdateChannel::Beta,
            },
            copy_worktree_include: self.copy_worktree_include,
        }
    }
}

/// What the page sends to delete a worktree: the row as it was shown when
/// the user confirmed, so the core can refuse a row that has since changed.
#[derive(Debug, Clone, PartialEq, Deserialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DeleteRequest {
    pub repo_id: String,
    pub path: String,
    pub expected_branch: Option<String>,
    /// Discard uncommitted changes: only after the second question.
    pub force: bool,
}

/// How a delete ended. The page asks again, louder, on `dirty`.
#[derive(Debug, Clone, PartialEq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub struct DeleteResult {
    pub ok: bool,
    pub refusal: Option<DeleteRefusal>,
    pub message: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export)]
pub enum DeleteRefusal {
    /// Uncommitted changes: ask before forcing.
    Dirty,
    /// The worktree no longer matches the row.
    Changed,
    Error,
}

// MARK: From the core

impl DeleteRequest {
    pub fn to_core(self) -> wtm_core::DeleteWorktreeParams {
        wtm_core::DeleteWorktreeParams {
            repo_id: self.repo_id,
            worktree_path: self.path,
            expected_branch: self.expected_branch,
            force: self.force,
        }
    }
}

impl DeleteResult {
    pub fn from_core(r: wtm_core::DeleteWorktreeResult) -> Self {
        Self {
            ok: r.ok,
            refusal: r.reason.map(|r| match r {
                wtm_core::DeleteRefusal::Dirty => DeleteRefusal::Dirty,
                wtm_core::DeleteRefusal::Changed => DeleteRefusal::Changed,
                wtm_core::DeleteRefusal::Error => DeleteRefusal::Error,
            }),
            message: r.message,
        }
    }
}

impl Model {
    pub fn from_core(m: &wtm_core::Model) -> Self {
        Self {
            repos: m.repos.iter().map(|n| Repo::from_core(m, n)).collect(),
            notice: m.notice.as_ref().map(|n| Notice {
                id: n.id,
                tone: match n.tone {
                    wtm_core::model::Tone::Info => Tone::Info,
                    wtm_core::model::Tone::Error => Tone::Error,
                },
                text: n.text.clone(),
            }),
            refreshing: m.refreshing,
            fetching: m.fetching,
            settings: Settings {
                worktrees_root: m.config.worktrees_root.clone(),
                editor_command: m.config.editor_command.clone(),
                copy_worktree_include: m.config.copy_worktree_include,
                update_channel: match m.config.update_channel {
                    wtm_core::update::UpdateChannel::Stable => UpdateChannel::Stable,
                    wtm_core::update::UpdateChannel::Beta => UpdateChannel::Beta,
                },
            },
        }
    }
}

impl Repo {
    fn from_core(m: &wtm_core::Model, n: &wtm_core::RepoNode) -> Self {
        Self {
            id: n.repo.id.clone(),
            name: n.repo.name.clone(),
            path: n.repo.path.clone(),
            display_path: tildify(&n.repo.path, &m.home),
            main_branch: n.repo.main_branch.clone(),
            init_command: n.repo.init_command.clone(),
            branches: n.branches.clone(),
            default_base_ref: n.default_base_ref.clone(),
            base_ref_candidates: n.base_ref_candidates.clone(),
            error: n.error.clone(),
            loaded: n.loaded,
            worktrees: n
                .worktrees
                .iter()
                .map(|w| Worktree {
                    path: w.path.clone(),
                    display_path: tildify(&w.path, &m.home),
                    branch: w.branch.clone(),
                    head: w.head.clone(),
                    is_main: w.is_main,
                    locked: w.locked,
                    prunable: w.prunable,
                    busy: m.busy_for(&w.path).map(Busy::from_core),
                    status: w.status.as_ref().map(|s| Status {
                        has_staged: s.has_staged,
                        has_unstaged: s.has_unstaged,
                        has_untracked: s.has_untracked,
                        trunk_ref: s.trunk_ref.clone(),
                        ahead: s.ahead_of_main,
                        behind: s.behind_main,
                        has_upstream: s.has_upstream,
                        unpushed: if s.unpushed { s.unpushed_count } else { 0 },
                    }),
                })
                .collect(),
            pending: m
                .pending_for(&n.repo.id)
                .map(|p| Pending {
                    id: p.id,
                    branch: p.branch.clone(),
                    folder: slugify_branch(&p.branch),
                    error: p.error.clone(),
                })
                .collect(),
        }
    }
}

impl Busy {
    fn from_core(b: wtm_core::Busy) -> Self {
        match b {
            wtm_core::Busy::Pushing => Busy::Pushing,
            wtm_core::Busy::Pulling => Busy::Pulling,
            wtm_core::Busy::Merging => Busy::Merging,
            wtm_core::Busy::Switching => Busy::Switching,
            wtm_core::Busy::Deleting => Busy::Deleting,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeMap;
    use wtm_core::{AppConfig, RepoConfig, RepoNode, WorktreeInfo, WorktreeStatus};

    fn core_model() -> wtm_core::Model {
        let repo = RepoConfig {
            id: "r1".into(),
            name: "app".into(),
            path: "/home/u/src/app".into(),
            main_branch: "main".into(),
            init_command: String::new(),
            commands: Vec::new(),
        };
        let status = WorktreeStatus {
            has_unstaged: true,
            has_staged: false,
            has_untracked: false,
            trunk_ref: "origin/main".into(),
            ahead_of_main: Some(2),
            behind_main: Some(0),
            unpushed: false,
            unpushed_count: 3,
            has_upstream: true,
        };
        let wt = WorktreeInfo {
            path: "/home/u/wt/app/fix".into(),
            branch: Some("fix".into()),
            head: "abc1234".into(),
            is_main: false,
            locked: false,
            prunable: false,
            status: Some(status),
        };
        wtm_core::Model {
            config: AppConfig {
                worktrees_root: "/home/u/wt".into(),
                editor_command: "code".into(),
                update_channel: Default::default(),
                copy_worktree_include: false,
                repos: vec![repo.clone()],
            },
            repos: vec![RepoNode {
                worktrees: vec![wt],
                ..RepoNode::placeholder(repo)
            }],
            busy: BTreeMap::from([("/home/u/wt/app/fix".to_string(), wtm_core::Busy::Pushing)]),
            pending: vec![wtm_core::PendingCreation {
                id: 7,
                repo_id: "r1".into(),
                branch: "next".into(),
                error: None,
            }],
            notice: None,
            refreshing: true,
            fetching: false,
            home: "/home/u".into(),
        }
    }

    #[test]
    fn paths_are_shown_from_home_and_busy_lands_on_its_row() {
        let m = Model::from_core(&core_model());
        let repo = &m.repos[0];
        assert_eq!(repo.display_path, "~/src/app");
        let wt = &repo.worktrees[0];
        assert_eq!(wt.display_path, "~/wt/app/fix");
        assert_eq!(wt.busy, Some(Busy::Pushing));
        assert_eq!(repo.pending[0].branch, "next");
    }

    #[test]
    fn unpushed_counts_only_when_git_says_there_is_something_unpushed() {
        let m = Model::from_core(&core_model());
        assert_eq!(m.repos[0].worktrees[0].status.as_ref().unwrap().unpushed, 0);
    }

    #[test]
    fn serialises_in_camel_case() {
        let json = serde_json::to_value(Model::from_core(&core_model())).unwrap();
        let wt = &json["repos"][0]["worktrees"][0];
        assert_eq!(wt["displayPath"], "~/wt/app/fix");
        assert_eq!(wt["busy"], "pushing");
        assert_eq!(wt["status"]["hasUnstaged"], true);
    }

    fn fields(name: &str, new_branch: bool) -> NewWorktreeFields {
        NewWorktreeFields {
            repo_id: "r1".into(),
            name: name.into(),
            new_branch,
            base: String::new(),
        }
    }

    #[test]
    fn new_worktree_check_says_what_create_sends_and_where() {
        let mut m = core_model();
        m.repos[0].loaded = true;
        let c = NewWorktreeCheck::new(&m, &fields(" feature/x ", true), None);
        assert_eq!(
            c.create,
            Some(CreateRequest {
                repo_id: "r1".into(),
                branch: "feature/x".into(),
                source: BranchSource::New { base_ref: None },
            })
        );
        assert_eq!(c.folder.as_deref(), Some("~/wt/app/feature-x"));
        let json = serde_json::to_value(&c).unwrap();
        assert_eq!(json["create"]["source"]["kind"], "new");
        // `fix` is checked out already.
        let c = NewWorktreeCheck::new(&m, &fields("fix", false), None);
        assert!(c.create.is_none());
        assert_eq!(c.problem.as_deref(), Some("Branch already has a worktree."));
        let c = NewWorktreeCheck::new(&m, &fields("other", true), Some("~/wt/app/other"));
        assert!(c.problem.unwrap().starts_with("A folder is already there"));
        let c = NewWorktreeCheck::new(&m, &fields("", true), None);
        assert_eq!((c.problem.as_deref(), c.folder), (Some(""), None));
    }

    #[test]
    fn repo_edits_keep_a_name_and_default_the_trunk() {
        let repo = core_model().config.repos[0].clone();
        let saved = RepoEdit {
            repo_id: "r1".into(),
            name: "  ".into(),
            main_branch: "".into(),
            init_command: "bun i".into(),
        }
        .apply(&repo);
        assert_eq!(
            (saved.name.as_str(), saved.main_branch.as_str()),
            ("app", "main")
        );
        assert_eq!(saved.init_command, "bun i");
    }

    #[test]
    fn a_dirty_refusal_reaches_the_page_as_dirty() {
        let r = DeleteResult::from_core(wtm_core::DeleteWorktreeResult {
            ok: false,
            reason: Some(wtm_core::DeleteRefusal::Dirty),
            message: "dirty".into(),
        });
        let json = serde_json::to_value(r).unwrap();
        assert_eq!(json["refusal"], "dirty");
        let req: DeleteRequest = serde_json::from_value(serde_json::json!({
            "repoId": "r1", "path": "/p", "expectedBranch": null, "force": true
        }))
        .unwrap();
        assert!(req.to_core().force);
    }

    #[test]
    fn the_page_view_leaves_the_window_frame_alone() {
        let frame = wtm_core::WindowFrame {
            x: 10.0,
            y: 20.0,
            width: 800.0,
            height: 600.0,
        };
        let before = wtm_core::UiState {
            window: Some(frame),
            ..Default::default()
        };
        let view = ViewState {
            closed_repos: vec!["b".into(), "a".into()],
            scroll: f64::NAN,
            focus: Some(RowFocus {
                repo_id: "a".into(),
                worktree_path: Some("/w".into()),
            }),
        };
        let after = view.clone().apply(before);
        assert_eq!(after.window, Some(frame));
        assert_eq!(after.scroll, 0.0);
        // Read back, the cards come sorted (a set) and the rest as sent.
        let back = ViewState::from_core(&after);
        assert_eq!(back.closed_repos, vec!["a".to_string(), "b".to_string()]);
        assert_eq!(back.focus, view.focus);
    }
}
